   473                  struct sc_pkcs15_object **out_key_object)
   474  {
   475          struct sc_context *ctx = p15card->card->ctx;
   476  #ifdef ENABLE_OPENSSL
   477          struct sc_pkcs15_object *key_object = NULL;
   478          struct sc_pkcs15_prkey_info *key_info = NULL;
   479          X509 *x = NULL;
   480          BIO *mem = NULL;
   481          unsigned char *buff = NULL, *ptr = NULL;
   482          int rv;
   483
   484          LOG_FUNC_CALLED(ctx);
   485          if (out_key_object)
   486                  *out_key_object = NULL;
   487
   488          rv = sc_pkcs15_find_prkey_by_id(p15card, &((struct sc_pkcs15_cert_info *)cert_object->data)->id, &key_object);
   489          if (rv == SC_ERROR_OBJECT_NOT_FOUND)
   490                  LOG_FUNC_RETURN(ctx, SC_SUCCESS);
   491          LOG_TEST_RET(ctx, rv, "Find private key error");
   492
   493          key_info = (struct sc_pkcs15_prkey_info *) key_object->data;
   494
   495          sc_log(ctx, "CertValue(%"SC_FORMAT_LEN_SIZE_T"u) %p",
   496                 cert_object->content.len, cert_object->content.value);
   497          mem = BIO_new_mem_buf(cert_object->content.value, cert_object->content.len);
   498          if (!mem)
   499                  LOG_TEST_RET(ctx, SC_ERROR_INTERNAL, "MEM buffer allocation error");
   500
   501          x = d2i_X509_bio(mem, NULL);
   502          if (!x)
   503                  LOG_TEST_RET(ctx, SC_ERROR_INTERNAL, "x509 parse error");
   504
   505          buff = OPENSSL_malloc(i2d_X509(x,NULL) + EVP_MAX_MD_SIZE);
   506          if (!buff)
   507                  LOG_TEST_RET(ctx, SC_ERROR_OUT_OF_MEMORY, "OpenSSL allocation error");
   508
   509          ptr = buff;
   510          rv = i2d_X509_NAME(X509_get_subject_name(x), &ptr);
   511          if (rv <= 0)
   512                  LOG_TEST_RET(ctx, SC_ERROR_INTERNAL, "Get subject name error");
   513
   514          key_info->subject.value = malloc(rv);
   515          if (!key_info->subject.value)
   516                  LOG_TEST_RET(ctx, SC_ERROR_OUT_OF_MEMORY, "Subject allocation error");
   517
   518          memcpy(key_info->subject.value, buff, rv);
   519          key_info->subject.len = rv;
   520
   521          strlcpy(key_object->label, cert_object->label, sizeof(key_object->label));
   522
   523          rv = 0;
   524
   525          if (x)
   526                  X509_free(x);
   527          if (mem)
   528                  BIO_free(mem);
   529          if (buff)
   530                  OPENSSL_free(buff);
   531
   532          ERR_clear_error();
   533
   534          if (out_key_object)
   535                  *out_key_object = key_object;
   536
   537          sc_log(ctx, "Subject %s", sc_dump_hex(key_info->subject.value, key_info->subject.len));
   538          LOG_FUNC_RETURN(ctx, rv);
   539  #else
   540          LOG_FUNC_RETURN(ctx, SC_ERROR_NOT_SUPPORTED);
