   401          size_t               sign_data_size = 0;
   402          CK_OBJECT_HANDLE     key = CK_INVALID_HANDLE;
   403          unsigned char        in_buffer[1025], sig_buffer[512];
   404          CK_MECHANISM         mech = {0, NULL_PTR, 0};
   405          CK_ULONG             sig_len = sizeof(sig_buffer);
   406          size_t               to_process = 0;
   407          CK_TOKEN_INFO        info;
   408
   409          /* Process options*/
   410          if (set_mechanism(&data, &size, &mech) || size < 3)
   411                  return;
   412          login_type = data[0];
   413          data++; size--;
   414          if (!(pin = extract_word(&data, &size)))
   415                  return;
   416          opt_id = data;
   417          opt_id_len = get_buffer(&opt_id, size, &data, &size, 256);
   418
   419          /* Prepare buffer for signing */
   420          sign_data = data;
   421          if ((sign_data_size = get_buffer(&sign_data, size, &data, &size, 6000)) == 0)
   422                  goto end;
   423
   424          /* Initialize */
   425          if (fuzz_pkcs11_initialize(data, size, NULL, &session) != CKR_OK)
   426                  goto end;
   427          p11->C_GetTokenInfo(0, &info);
   428          p11->C_Login(session, login_type, (CK_UTF8CHAR *) pin, strlen(pin));
   429          fuzz_find_object(session, CKO_PRIVATE_KEY, &key, opt_id_len ? opt_id : NULL, opt_id_len);
   430
   431          if (p11->C_SignInit(session, &mech, key) != CKR_OK)
   432                  goto fin;
   433          p11->C_Login(session, CKU_CONTEXT_SPECIFIC, (CK_UTF8CHAR *) pin, strlen(pin));
   434
   435          if (sign_data_size <= sizeof(in_buffer)) {
   436                  memcpy(in_buffer, sign_data, sign_data_size);
   437                  p11->C_Sign(session, in_buffer, sign_data_size, sig_buffer, &sig_len);
   438          } else {
   439                  while (sign_data_size > 0) {
   440                          to_process = sign_data_size < sizeof(in_buffer) ? sign_data_size : sizeof(in_buffer);
   441                          sign_data_size -= to_process;
   442                          memcpy(in_buffer, sign_data, to_process);
   443                          sign_data += to_process;
   444
   445                          if (p11->C_SignUpdate(session, in_buffer, to_process) != CKR_OK)
   446                                  goto fin;
   447                  }
   448
   449                  sig_len = sizeof(sig_buffer);
   450                  p11->C_SignFinal(session, sig_buffer, &sig_len);
   451          }
   452
   453  fin:
   454          p11->C_CloseSession(session);
   455          p11->C_Finalize(NULL);
   456  end:
   457          free(pin);
   458  }
