   647  int fill_key_template(CK_ATTRIBUTE **keyTemplate, int *n_attr, const uint8_t **data, size_t *size, CK_OBJECT_CLASS *class, int token)
   648  {
   649          const unsigned char *ptr = NULL;
   650          size_t               ecparams_size = 0;
   651          size_t               opt_object_label_size = 0;
   652          size_t               opt_object_id_len = 0;
   653          size_t               opt_allowed_mechanisms_len = 0;
   654          int bool_types[] = {CKA_MODULUS_BITS, CKA_PUBLIC_EXPONENT, CKA_VERIFY, CKA_SENSITIVE,
   655                                                  CKA_SIGN, CKA_ENCRYPT, CKA_DECRYPT, CKA_WRAP, CKA_UNWRAP,
   656                                                  CKA_DERIVE, CKA_PRIVATE, CKA_ALWAYS_AUTHENTICATE, CKA_EXTRACTABLE};
   657
   658          if (!(*keyTemplate = malloc(20 * sizeof(CK_ATTRIBUTE))))
   659                  return 1;
   660          memset(*keyTemplate, 0, 20 * sizeof(CK_ATTRIBUTE));
   661          FILL_ATTR((*keyTemplate)[0], CKA_CLASS, class, sizeof(CKA_CLASS));
   662          *n_attr = 1;
   663          fill_bool_attr(keyTemplate, n_attr, CKA_TOKEN, token);
   664
   665          for (int i = 0; i < 13; i++) {
   666                  /* ... | present -> 0/1 | value | ...*/
   667                  if (*size < 3)
   668                          return 1;
   669                  if ((*data)[0] % 2) {
   670                          fill_bool_attr(keyTemplate, n_attr, bool_types[i], (*data)[1] % 2);
   671                          (*data)++; (*size)--;
   672                  }
   673                  (*data)++; (*size)--;
